definition.script:
pipeline {
    agent any

    tools {
        maven 'maven3.9'
        jdk 'jdk17'
    }

    stages {
        stage('Git Checkout') {
            steps {
                git branch: 'main', url: 'https://github.com/sandhya-en/Boardgame.git'
            }
        }
         stage('Compile') {
            steps {
                echo 'mvn compile'
            }
        }
         stage('Test') {
            parallel {
                stage('Unit') {
            steps {
                sh "echo unit"
            }
        }

        stage('Integration') {
            steps {
                sh "echo Integ"
            }
        }

        stage('PenTest') {
            steps {
               sh "echo Pentest"
            }
        }
            }
        }

        stage('Build') {
            steps {
                echo 'mvn package'
            }
        }
    }
}
